parameters.jsonBody:
={
  "model": "devstral:24b",
  "prompt": "Извлеки из текста позиции прайс-листа структурированные данные для внесения в справочник цен строительных работ.\n\nТекст позиции: \"" + $json.row_text.replace(/"/g, '\\"') + "\"\n\nВерни JSON: source_work_name — название работы как в тексте (без цены и единицы измерения); unit — единица измерения (например 'кв.м', 'шт.', 'м.п.'); price — число, цена без валюты (или null, если цена не указана/по договору); price_qualifier — одно из: exact (точная цена), from (цена от), approx (примерная), on_request (по договору, число не указано); confidence — насколько уверенно распознаны цифры и единица измерения в этом фрагменте (low/medium/high).",
  "format": {
    "type": "object",
    "properties": {
      "source_work_name": {"type": "string"},
      "unit": {"type": "string"},
      "price": {"type": ["number", "null"]},
      "price_qualifier": {"type": "string", "enum": ["exact", "from", "approx", "on_request"]},
      "confidence": {"type": "string", "enum": ["low", "medium", "high"]}
    },
    "required": ["source_work_name", "unit", "price_qualifier", "confidence"]
  },
  "stream": false
}
